import torch.nn as nn
from torch.utils.cpp_extension import load_inline
source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define THREADS 256
#define BPC 4
__global__ void bn_stats_partial_kernel(
    const float* __restrict__ x,
    float* __restrict__ partial_sum,
    float* __restrict__ partial_sumsq,
    int N, int C, int H, int W) {
    int c = blockIdx.x / BPC;
    int part = blockIdx.x % BPC;
    long HW = (long)H * W;
    long count = (long)N * HW;
    bool vec_ok = ((HW & 3L) == 0);
    long chunk = (count + BPC - 1) / BPC;
    if (vec_ok) {
        chunk = (chunk + 3L) & ~3L;
    }
    long start = (long)part * chunk;
    long end = start + chunk;
    if (end > count) end = count;
    float sum = 0.0f;
    float sumsq = 0.0f;
    if (vec_ok && start < end) {
        long vstart = start >> 2;
        long vend = end >> 2;
        for (long v = vstart + threadIdx.x; v < vend; v += blockDim.x) {
            long i = v << 2;
            long n = i / HW;
            long hw = i % HW;
            long idx = ((long)n * C + c) * HW + hw;
            const float4* p4 = reinterpret_cast<const float4*>(x + idx);
            float f0, f1, f2, f3;
            asm volatile("ld.global.v4.f32 {%0,%1,%2,%3}, [%4];"
                : "=f"(f0), "=f"(f1), "=f"(f2), "=f"(f3)
                : "l"(p4));
            sum += f0 + f1 + f2 + f3;
            sumsq += f0 * f0 + f1 * f1 + f2 * f2 + f3 * f3;
        }
    } else {
        for (long i = start + threadIdx.x; i < end; i += blockDim.x) {
            long n = i / HW;
            long hw = i % HW;
            long idx = ((long)n * C + c) * HW + hw;
            float val = x[idx];
            sum += val;
            sumsq += val * val;
        }
    }
    __shared__ float s_sum[THREADS];
    __shared__ float s_sumsq[THREADS];
    s_sum[threadIdx.x] = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 32; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x < 32) {
        float v_sum = s_sum[threadIdx.x] + s_sum[threadIdx.x + 32];
        float v_sumsq = s_sumsq[threadIdx.x] + s_sumsq[threadIdx.x + 32];
        for (int offset = 16; offset > 0; offset >>= 1) {
            float shfl_sum, shfl_sumsq;
            asm volatile("shfl.sync.down.b32 %0, %1, %2, 0x1f, 0xffffffff;" : "=f"(shfl_sum) : "f"(v_sum), "r"(offset));
            asm volatile("shfl.sync.down.b32 %0, %1, %2, 0x1f, 0xffffffff;" : "=f"(shfl_sumsq) : "f"(v_sumsq), "r"(offset));
            v_sum += shfl_sum;
            v_sumsq += shfl_sumsq;
        }
        if (threadIdx.x == 0) {
            partial_sum[c * BPC + part] = v_sum;
            partial_sumsq[c * BPC + part] = v_sumsq;
        }
    }
}
__global__ void bn_stats_finalize_kernel(
    const float* __restrict__ partial_sum,
    const float* __restrict__ partial_sumsq,
    float* __restrict__ mean,
    float* __restrict__ var,
    long count,
    int C) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float s = 0.0f;
    float sq = 0.0f;
    #pragma unroll
    for (int p = 0; p < BPC; p++) {
        s += partial_sum[c * BPC + p];
        sq += partial_sumsq[c * BPC + p];
    }
    float m = s / (float)count;
    float v = sq / (float)count - m * m;
    mean[c] = m;
    var[c] = v;
}
__global__ void update_running_stats_kernel(
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    float momentum,
    long count,
    int C) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float unbiased_var = var[c] * (float)count / (float)(count - 1);
    running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean[c];
    running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
}
__global__ void bn_apply_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float eps,
    int N, int C, int H, int W) {
    long HW = (long)H * W;
    long total = (long)N * C * HW;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;
    long hw = idx % HW;
    long tmp = idx / HW;
    int c = tmp % C;
    long n = tmp / C;
    float m = mean[c];
    float v = var[c];
    float g = gamma[c];
    float b = beta[c];
    float inv_std;
    asm volatile("rsqrt.approx.f32 %0, %1;" : "=f"(inv_std) : "f"(v + eps));
    long in_idx = ((long)n * C + c) * HW + hw;
    float val = x[in_idx];
    float norm = (val - m) * inv_std;
    float out;
    asm volatile("fma.rn.f32 %0, %1, %2, %3;" : "=f"(out) : "f"(norm), "f"(g), "f"(b));
    y[in_idx] = out;
}
torch::Tensor batch_norm_forward(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    float momentum,
    float eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    x = x.contiguous();
    gamma = gamma.contiguous();
    beta = beta.contiguous();
    running_mean = running_mean.contiguous();
    running_var = running_var.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    auto y = torch::empty_like(x);
    torch::Tensor mean;
    torch::Tensor var;
    if (training) {
        mean = torch::empty({C}, x.options());
        var = torch::empty({C}, x.options());
        auto partial_sum = torch::empty({(long)C * BPC}, x.options());
        auto partial_sumsq = torch::empty({(long)C * BPC}, x.options());
        bn_stats_partial_kernel<<<C * BPC, THREADS>>>(
            x.data_ptr<float>(),
            partial_sum.data_ptr<float>(),
            partial_sumsq.data_ptr<float>(),
            N, C, H, W);
        long count = (long)N * H * W;
        int fthreads = 256;
        int fblocks = (C + fthreads - 1) / fthreads;
        bn_stats_finalize_kernel<<<fblocks, fthreads>>>(
            partial_sum.data_ptr<float>(),
            partial_sumsq.data_ptr<float>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            count,
            C);
        int uthreads = 256;
        int ublocks = (C + uthreads - 1) / uthreads;
        update_running_stats_kernel<<<ublocks, uthreads>>>(
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            momentum,
            count,
            C);
    } else {
        mean = running_mean;
        var = running_var;
    }
    long total = (long)N * C * H * W;
    int threads = 256;
    long blocks = (total + threads - 1) / threads;
    bn_apply_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        eps,
        N, C, H, W);
    return y;
}
